#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/panel/picture_box/picture_box_values/picture_box_values.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// PictureBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/picture_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The generational image resource shown (Image); an ImageId into the window's ImageRegistry. A change raises image_changed. clear_image() resets it.
template <typename Declaring>
struct PictureBoxImageCapability {
    PropertyCell<ImageId, PictureBoxImageCapability<Declaring>> image{};

    static void assign(PictureBoxImageCapability& capability, ImageId incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image), incoming);
        if (!capability.image.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image));
    }
};

// How the image is placed and scaled (SizeMode): normal, stretch_image, auto_size, center_image or zoom.
template <typename Declaring>
struct PictureBoxSizeModePropertyCapability {
    PropertyCell<PictureBoxSizeMode, PictureBoxSizeModePropertyCapability<Declaring>> size_mode{PictureBoxSizeMode::normal};

    static void assign(PictureBoxSizeModePropertyCapability& capability, PictureBoxSizeMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.size_mode), incoming);
        if (!capability.size_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.size_mode));
    }
};

// The image's opacity from zero through one; anything else, or a value that is not finite, throws std::invalid_argument.
template <typename Declaring>
struct PictureBoxImageOpacityCapability {
    PropertyCell<double, PictureBoxImageOpacityCapability<Declaring>> image_opacity{1.0};

    static void assign(PictureBoxImageOpacityCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_opacity), incoming);
        if (!capability.image_opacity.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_opacity));
    }
};

// PictureBoxSizeMode as a property value; defined beside PictureBox's table.
template <>
struct PropertyValueTraits<PictureBoxSizeMode> {
    static PropertyType type();
    static BindingValue to_binding(PictureBoxSizeMode value);
    static PictureBoxSizeMode from_binding(const BindingValue& value);
};

// Every PictureBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct PictureBoxCapabilities : public PictureBoxImageCapability<Declaring>,
                                public PictureBoxSizeModePropertyCapability<Declaring>,
                                public PictureBoxImageOpacityCapability<Declaring> {};

} // namespace gui_forms
